(()=>{'use strict';const A=RepoAccount,$=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));window.RepoLaunchAnalytics=(data,rows=[])=>{if(!data?.configured)return '<section class="analytics-box"><h3>Discovery conversions</h3><p>Apply migration 10 to activate conversion tracking. Existing visitor counts remain available.</p></section>';const rate=(n,d)=>d?Math.round(n/d*1000)/10+'%':'—',metric=(n,d,label)=>`<div class="metric"><strong>${rate(n,d)}</strong><span>${esc(label)}</span><small>${Number(n||0)} of ${Number(d||0)} listing sessions</small></div>`,names=new Map(rows.map(r=>[r.builtin_key||r.id,r.title]));return `<section class="analytics-box"><h3>From discovery to making it your own</h3><div class="conversion-grid">${metric(data.viewToDemo,data.listingSessions,'Listing → demo')}${metric(data.viewToLike,data.listingSessions,'Listing → like')}${metric(data.demoToLike,data.demoSessions,'Demo → like')}${metric(data.signInCompletions,data.signInStarts,'Sign-in completion')}<div class="metric"><strong>${Number(data.verifiedForks||0)}</strong><span>Newly verified forks</span><small>${Number(data.forkClicks||0)} fork / duplicate clicks</small></div><div class="metric"><strong>${Number(data.returningVisitors||0)}</strong><span>Returning browsers</span></div></div><p class="analytics-caption">Tracking began ${esc(new Date(data.startedAt).toLocaleDateString())}. Conversions count sessions with the same listing and an observed sequence. Demo clicks do not prove demo usage or cause a like. Returning browsers appeared on more than one UTC day in this range. Verified forks are newly observed during a fork check, not proof of a fork created through RepoShelf.</p><h4>Storefront row activity</h4><table class="analytics-table"><thead><tr><th>Row</th><th>Listing views</th><th>Demos</th><th>Likes</th><th>Fork clicks</th></tr></thead><tbody>${(data.rows||[]).map(r=>`<tr><td>${esc(names.get(r.shelf)||({all:'All projects',direct:'Direct listing',hero:'In the spotlight'})[r.shelf]||r.shelf)}</td><td>${Number(r.listing_views)}</td><td>${Number(r.demo_clicks)}</td><td>${Number(r.likes)}</td><td>${Number(r.fork_clicks)}</td></tr>`).join('')||'<tr><td colspan="5">Activity will appear after eligible visits.</td></tr>'}</tbody></table></section>`};
let epoch=0,quality=[],reports=[],editing=null,offset=0,reportOffset=0,timer;
const issueNames={browser_unattempted:'Browser work never attempted',browser_repeated:'Repeated browser failures',repository_check:'Repository check due',demo_check:'Demo check due',broken_demo:'Demo needs attention',retry:'Awaiting retry',screenshot:'Missing screenshot',description:'Short description',licence:'Licence missing',category:'Category missing',unavailable:'Unavailable',hidden:'Hidden or excluded',excluded:'Permanently excluded'};
function error(slot,e){if(e.status===401||e.status===403)void A.refresh();slot.innerHTML=`<p class="loading-note">${esc(e.message)}</p>${e.code==='migration_required'?'<p>Apply <a href="https://github.com/sparx1981/RepoShelf/blob/main/supabase/migrations/202610040010_launch_quality_moderation_analytics.sql" target="_blank" rel="noopener">migration 10</a>, then refresh this tab.</p>':''}`}
async function loadQuality(append=false){const token=++epoch;if(!append)offset=0;const slot=$('#quality-content');if(!append)slot.innerHTML='<p>Loading catalogue quality…</p>';try{const data=await A.request('/api/editorial?action=quality&offset='+offset+'&issue='+encodeURIComponent($('#quality-issue').value)+'&q='+encodeURIComponent($('#quality-search').value));if(token!==epoch||!A.user?.admin)return;quality=append?[...quality,...data.items]:data.items;offset=data.nextOffset;const c=data.coverage,metric=(n,label,suffix='')=>`<div class="metric"><strong>${Number(n||0).toLocaleString()}${suffix}</strong><span>${esc(label)}</span></div>`;slot.innerHTML=`<div class="metric-grid">${metric(c.total,'Saved projects')}${metric(c.repositoryCoverage,'Repository check coverage','%')}${metric(c.demoCoverage,'Demo validation coverage','%')}${metric(c.screenshotCoverage,'Demo screenshot coverage','%')}${metric(c.featuredEligible,'Ready to feature')}${metric(c.screenshot,'Missing screenshots')}${metric(c.demo_check,'Demo checks due')}${metric(c.broken_demo,'Demos needing attention')}${metric(c.retry,'Awaiting retries')}${metric(c.browserBacklog?.demo.never,'Demo validation never attempted')}${metric(c.browserBacklog?.screenshot.never,'Screenshot never attempted')}${metric(c.browserBacklog?.demo.repeated,'Repeated demo failures')}${metric(c.browserBacklog?.screenshot.repeated,'Repeated screenshot failures')}${metric(c.browserBacklog?.reviewCount,'Listings needing manual review')}</div><p class="analytics-caption">Counts reflect the published catalogue; Sync log shows newer saved progress. Repeated failures mean at least three consecutive attempts. Featured listings need a successful demo check in the last seven days and a usable preview. Queue order: featured selections, frequently viewed listings, then completeness. Refresh requests are picked up by the next scheduled maintenance run.</p><section class="analytics-box"><h3>Launch quality targets</h3><table class="analytics-table"><thead><tr><th>Check</th><th>Coverage</th><th>Target</th><th>Status</th></tr></thead><tbody>${(data.targets||[]).map(t=>`<tr><td>${esc(t.label)}</td><td>${Number(t.actual)}%</td><td>${Number(t.target)}%</td><td>${t.met?'Met':'Needs attention'}</td></tr>`).join('')}</tbody></table><p class="analytics-caption">Targets measure saved evidence. Review every featured screenshot and description by hand before launch; passing automated checks does not confirm every demo feature works.</p></section><div class="quality-list">${quality.map(r=>`<article class="quality-item"><div><strong>${esc(r.name)}</strong><small>${esc(r.id)} · ${esc(r.control.visibility)}${r.featured?' · Featured selection':''}${r.featuredEligible?' · Ready to feature':''}</small><p>${r.issues.map(i=>esc(issueNames[i]||i)).join(' · ')||'No quality issues detected'}</p></div>${r.browserBacklog?.reason?`<p class="small">Last browser issue: ${esc(r.browserBacklog.reason.replaceAll('_',' '))} · ${Number(r.browserBacklog.demoFailures)} consecutive demo failures · ${Number(r.browserBacklog.previewFailures)} consecutive capture failures${r.browserBacklog.nextRetryAt?' · Retry after '+esc(new Date(r.browserBacklog.nextRetryAt).toLocaleString()):''}</p>`:''}${r.browserBacklog?.reviewAdvice?`<p class="small">${esc(r.browserBacklog.reviewAdvice)}</p>`:''}<button class="button outline" data-quality-edit="${esc(r.id)}">Review listing</button></article>`).join('')||'<p>No matching listings.</p>'}</div>${offset!==null?'<button class="button outline" id="quality-more">Load more</button>':''}<details class="analytics-box"><summary>Coverage history</summary><table class="analytics-table"><thead><tr><th>Date</th><th>Records</th><th>Previews</th><th>Unavailable</th></tr></thead><tbody>${(data.history||[]).map(r=>`<tr><td>${esc(r.at?.slice(0,10))}</td><td>${Number(r.records||0)}</td><td>${Number(r.withScreenshot||0)}</td><td>${Number(r.unavailable||0)}</td></tr>`).join('')}</tbody></table><p class="analytics-caption">Historical previews can include author-provided images; current missing-screenshot counts require a captured demo image.</p></details>`;$('#quality-more')?.addEventListener('click',()=>loadQuality(true))}catch(e){if(token===epoch&&A.user?.admin)error(slot,e)}}
async function loadReports(append=false){const token=++epoch;if(!append)reportOffset=0;const slot=$('#reports-content');try{const data=await A.request('/api/editorial?action=reports&status='+$('#reports-status').value+'&offset='+reportOffset);if(token!==epoch||!A.user?.admin)return;reports=append?[...reports,...data.items]:data.items;reportOffset=data.nextOffset;slot.innerHTML=reports.map(r=>`<article class="quality-item report-item"><div><strong>${esc(r.project_id)}</strong><small>${esc(r.reason.replaceAll('_',' '))} · ${esc(r.status)} · ${esc(new Date(r.created_at).toLocaleString())}</small><p>${esc(r.explanation)||'No additional explanation.'}</p><div class="report-actions"><button class="button outline" data-report-listing="${esc(r.project_id)}">Review listing</button>${r.status==='open'?`<button class="button outline" data-review-report="${r.id}" data-status="reviewed">Mark reviewed</button><button class="button outline" data-review-report="${r.id}" data-status="dismissed">Dismiss report</button>`:''}</div></div></article>`).join('')||'<p>No reports in this view.</p>';if(reportOffset!==null)slot.insertAdjacentHTML('beforeend','<button class="button outline" id="reports-more">Load more</button>');$('#reports-more')?.addEventListener('click',()=>loadReports(true))}catch(e){if(token===epoch&&A.user?.admin)error(slot,e)}}
async function editListing(id){let row=quality.find(r=>r.id===id);if(!row){$('#quality-search').value=id;$('#quality-issue').value='';await loadQuality();row=quality.find(r=>r.id.toLowerCase()===id.toLowerCase())}if(!row||!A.user?.admin)return;editing=row;const c=row.control;$('#moderation-title').textContent=row.name;$('#moderation-id').textContent=row.id;$('#moderation-description').value=c.description||'';$('#moderation-original').textContent=row.authorDescription;$('#moderation-category').value=c.category||'';$('#moderation-visibility').value=c.visibility;$('#moderation-reject').checked=c.preview_rejected;$('#moderation-refresh').checked=false;$('#moderation-note').value='';$('#moderation-message').textContent='';const image=$('#moderation-preview');image.hidden=!row.preview;image.src=row.preview?.src||'';$('#moderation-dialog').showModal();const token=epoch;try{const data=await A.request('/api/editorial?action=audit&id='+encodeURIComponent(id));if(token!==epoch||editing?.id!==id||!A.user?.admin)return;$('#moderation-audit').innerHTML=data.items.map(r=>`<p><strong>${esc(r.action.replaceAll('_',' '))}</strong> · ${esc(new Date(r.created_at).toLocaleString())}<br>${esc(r.note)}<small>Administrator account: ${esc(r.actor||'Removed account')}</small></p>`).join('')||'<p>No moderation changes yet.</p>'}catch(e){if(A.user?.admin)$('#moderation-audit').textContent=e.message}}
$('#moderation-form').onsubmit=async event=>{event.preventDefault();if(!editing)return;const row=editing,button=$('#moderation-save');button.disabled=true;try{await A.request('/api/editorial?action=moderate',{method:'POST',body:JSON.stringify({id:row.id,revision:row.control.revision,visibility:$('#moderation-visibility').value,description:$('#moderation-description').value,category:$('#moderation-category').value,rejectPreview:$('#moderation-reject').checked,preview:row.preview?.src||row.control.rejected_preview||null,refresh:$('#moderation-refresh').checked,note:$('#moderation-note').value})});$('#moderation-dialog').close();void loadQuality()}catch(e){$('#moderation-message').textContent=e.message;if(e.status===409){$('#moderation-dialog').close();await loadQuality()}}finally{button.disabled=false}};
$('#moderation-dialog .close').onclick=()=>$('#moderation-dialog').close();$('#refresh-quality').onclick=()=>loadQuality();$('#quality-issue').onchange=()=>loadQuality();$('#quality-search').oninput=()=>{clearTimeout(timer);timer=setTimeout(()=>loadQuality(),250)};$('#refresh-reports').onclick=()=>loadReports();$('#reports-status').onchange=()=>loadReports();
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(b?.dataset.adminTab==='quality')void loadQuality();if(b?.dataset.adminTab==='reports')void loadReports();if(b?.dataset.qualityEdit)void editListing(b.dataset.qualityEdit);if(b?.dataset.reportListing)void editListing(b.dataset.reportListing);if(b?.dataset.reviewReport){const note=prompt('Add a private review note (optional):');if(note===null)return;const report=reports.find(r=>r.id===b.dataset.reviewReport);b.disabled=true;try{await A.request('/api/editorial?action=review-report',{method:'POST',body:JSON.stringify({id:report.id,revision:report.revision,status:b.dataset.status,note})});await loadReports()}catch(err){error($('#reports-content'),err)}}});
window.addEventListener('reposhelf-account',()=>{if(!A.user?.admin){epoch++;quality=[];reports=[];editing=null;$('#quality-content').innerHTML='';$('#reports-content').innerHTML='';$('#moderation-audit').innerHTML='';$('#moderation-form').reset();$('#moderation-original').textContent='';$('#moderation-preview').removeAttribute('src');$('#moderation-dialog').close()}else{const tab=new URL(location.href).searchParams.get('tab');if(tab==='quality')void loadQuality();if(tab==='reports')void loadReports()}});
if(A.user?.admin){const tab=new URL(location.href).searchParams.get('tab');if(tab==='quality')void loadQuality();if(tab==='reports')void loadReports()}
})();
